/* paleta LS Fire: laranja da marca + famílias monocromática, terra e análoga (ver :root no CSS) */
const PAL=['#3B5B86','#16807F','#B26A00','#B0457A','#5B6B7F','#6E7F2E','#1F2328'];
const C_OK='#18794A', C_ERRO='#C0281C', C_ALERTA='#B26A00', C_LAR='#3B5B86', C_AZ='#16807F',
      C_CINZA='#9AA4B1', C_ROXO='#B0457A', C_CIANO='#6E7F2E';
const cor=i=>PAL[i%PAL.length];

/* ---------- utilidades ---------- */
const norm=s=>(s==null?'':String(s)).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9%]+/g,' ').trim();
const fmtBRL=v=>(v==null||isNaN(v))?'—':'R$ '+Number(v).toLocaleString('pt-BR',{maximumFractionDigits:0});
const fmtCompacto=v=>{v=Number(v)||0;const a=Math.abs(v);
  if(a>=1e9)return'R$ '+(v/1e9).toLocaleString('pt-BR',{maximumFractionDigits:2})+' bi';
  if(a>=1e6)return'R$ '+(v/1e6).toLocaleString('pt-BR',{maximumFractionDigits:2})+' mi';
  if(a>=1e3)return'R$ '+(v/1e3).toLocaleString('pt-BR',{maximumFractionDigits:0})+' mil';
  return'R$ '+v.toLocaleString('pt-BR',{maximumFractionDigits:0});};
const fmtN=v=>(v==null||isNaN(v))?'—':Number(v).toLocaleString('pt-BR',{maximumFractionDigits:0});
const fmtD=(v,d=1)=>(v==null||isNaN(v))?'—':Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const fmtPct=(v,d=1)=>(v==null||isNaN(v)||!isFinite(v))?'—':fmtD(v*100,d)+'%';
const fmtData=d=>d instanceof Date&&!isNaN(d)?d.toLocaleDateString('pt-BR'):'—';
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
/* DATA DE REFERÊNCIA DA ANÁLISE: tudo que diz "hoje" (mês em curso, meta até
   hoje, vencido, atrasado, parado) usa esta data. Padrão = data do computador;
   o usuário pode fixar outra para reproduzir um relatório passado. */
let REF_DATA=null;
/* "hoje" no fuso de São Paulo, qualquer que seja o relógio do computador */
const hojeReal=()=>{ try{ const [a,m,d]=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).split('-').map(Number); return new Date(a,m-1,d); }catch(e){ return new Date(new Date().toDateString()); } };
const hoje=()=>REF_DATA?new Date(+REF_DATA):hojeReal();
const diasEntre=(a,b)=>(a&&b)?Math.round((b-a)/864e5):null;
const mesKey=d=>d?d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'):null;
const MESES=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
const mesRot=k=>{if(!k)return'—';const[a,m]=k.split('-');return MESES[+m-1]+'/'+a.slice(2);};
/* ---------- leitura de número e data com validação ----------
   Ausência é null (nunca zero). "1.234" sem vírgula é milhar no padrão
   brasileiro (1234), não 1,234; "1.5" continua 1,5. Data impossível
   ("31/02/2026") não é aceita nem "rola" para março: vira null e fica
   registrada em VALIDACAO para o aviso da importação. */
const VALIDACAO={datas:[],numeros:[]};
const _anota=(lista,v)=>{ if(lista.length<200)lista.push(String(v)); };
function num(v){ if(v==null||v==='')return null; if(typeof v==='number')return isFinite(v)?v:null;
  let s=String(v).trim(); if(!s||/^[-–—]$/.test(s)||/^(n\/?d|n\/?a|-+)$/i.test(s))return null;
  const neg=/^\(.*\)$/.test(s)||/^-/.test(s.replace(/^R\$\s*/,''));
  s=s.replace(/[R$\s%()]/g,'').replace(/^-/,'');
  if(s.includes(',')&&s.includes('.')){ s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,''); }
  else if(s.includes(',')) s=s.replace(/\./g,'').replace(',','.');
  else if(/^[1-9]\d{0,2}(\.\d{3})+$/.test(s)){ if(/^\d{1,3}\.\d{3}$/.test(s))_anota(VALIDACAO.numeros,v); s=s.replace(/\./g,''); }
  if(!/^\d*\.?\d+(e[+-]?\d+)?$/i.test(s))return null;
  const n=parseFloat(s); return isNaN(n)?null:(neg?-n:n); }
const _dataOK=(a,m,d)=>{ const x=new Date(a,m-1,d); return x.getFullYear()===a&&x.getMonth()===m-1&&x.getDate()===d&&a>1990&&a<2100?x:null; };
function data(v){ if(v==null||v==='')return null;
  if(v instanceof Date)return isNaN(v)?null:new Date(v.getFullYear(),v.getMonth(),v.getDate());
  if(typeof v==='number'){ if(v>20000&&v<80000){ const d=new Date(Math.round((v-25569)*864e5)); return new Date(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()); } return null; }
  const s=String(v).trim(); if(!s)return null;
  let m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m){ const d=_dataOK(+m[1],+m[2],+m[3]); if(!d)_anota(VALIDACAO.datas,v); return d; }
  m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if(m){ const d=_dataOK(+m[3],+m[2],+m[1]); if(!d)_anota(VALIDACAO.datas,v); return d; }
  if(/^[a-z ]*confirmar|^n\/?d$|^-+$/i.test(s))return null;     /* "A CONFIRMAR": sem data, não é erro */
  const d=new Date(s); if(isNaN(d)){ if(/\d/.test(s))_anota(VALIDACAO.datas,v); return null; }
  return _dataOK(d.getFullYear(),d.getMonth()+1,d.getDate()); }
const somaBy=(arr,f)=>arr.reduce((s,x)=>s+(f(x)||0),0);
function agrupar(arr,chave){const m=new Map();arr.forEach(x=>{const k=chave(x)??'(vazio)';if(!m.has(k))m.set(k,[]);m.get(k).push(x);});return m;}
function rank(map,fn,n=10){return[...map.entries()].map(([k,v])=>({k,v,m:fn(v)})).sort((a,b)=>b.m-a.m).slice(0,n);}
const media=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
const mediana=a=>{if(!a.length)return null;const b=a.slice().sort((x,y)=>x-y),m=b.length>>1;return b.length%2?b[m]:(b[m-1]+b[m])/2;};
const pctl=(a,p)=>{if(!a.length)return null;const b=a.slice().sort((x,y)=>x-y);return b[Math.min(b.length-1,Math.max(0,Math.round((b.length-1)*p)))];};

/* ---------- nomes de vendedores unificados entre os sistemas ---------- */
/* O Controle de Pedidos usa o nome curto do time ("Fábio Elias", "Anderson",
   "Maria") enquanto o CRM e as metas usam o nome completo. Sem estes apelidos o
   realizado não encontra a meta e o vendedor aparece com 0%. */
const VEND={'fabio elias dalagnolo':'Fábio Dalagnolo','fabio dalagnolo':'Fábio Dalagnolo','fabinho':'Fábio Dalagnolo',
 'fabio elias':'Fábio Dalagnolo','fabio':'Fábio Dalagnolo',
 'anderson alencar':'Anderson Alencar','andy':'Anderson Alencar','anderson':'Anderson Alencar',
 'maria':'Conceição Reis','maria conceicao reis':'Conceição Reis',
 'guilherme valentim binatto':'Guilherme Binatto','guilherme binatto':'Guilherme Binatto','binatto':'Guilherme Binatto',
 'lucas marcius':'Lucas Marcius','lucas marcius santos':'Lucas Marcius',
 'lucas jacobsen':'Lucas Jacobsen','lucas de freitas jacobsen':'Lucas Jacobsen',
 'conceicao reis':'Conceição Reis','maria conceicao':'Conceição Reis','cissa':'Conceição Reis',
 'karl william hinsching':'Karl Hinsching','robson mafra':'Robson Mafra',
 'leomar boing junior':'Leomar Boing','leomar boing':'Leomar Boing',
 'bruno':'Bruno Viebranz','bruno viebranz':'Bruno Viebranz','adriana felipe bonanome':'Adriana Bonanome'};
let _vendFallback=null;
/* nome curto que bate com UM único nome canônico conhecido resolve sozinho;
   se empatar (dois "Lucas"), fica como veio — melhor um nome solto que o errado */
function vendFallback(){ if(_vendFallback)return _vendFallback;
  const canon=new Set(Object.values(VEND)); const m=new Map();
  canon.forEach(nome=>{ const n=norm(nome);
    [n.split(' ')[0], n].forEach(ch=>{ if(!ch)return;
      if(m.has(ch)&&m.get(ch)!==nome)m.set(ch,null); else if(!m.has(ch))m.set(ch,nome); }); });
  _vendFallback=m; return m; }
function vendedor(s){ const t=String(s||'').trim(); if(!t||t==='N/D')return '(sem responsável)';
  const n=norm(t);
  if(VEND[n])return VEND[n];
  const f=vendFallback().get(n); if(f)return f;
  return t.replace(/\s+/g,' '); }
const divCurta=s=>{const d=norm(s);
  if(!d)return '(sem divisão)';
  if(d.startsWith('seq')||d.startsWith('solucoes'))return 'SEQ';
  if(d.startsWith('spv')||d.startsWith('svp')||d.startsWith('servicos e pos')||d.startsWith('pos venda'))return 'SPV';
  return String(s).trim();};

