function mapear(cols,base){ const dic=CAMPOS[base], mapa={}, nc=cols.map(norm);
  for(const campo in dic){ for(const alias of dic[campo]){ const i=nc.indexOf(alias); if(i>=0){mapa[campo]=i;break;} }
    if(mapa[campo]===undefined){ for(const alias of dic[campo]){ const i=nc.findIndex(c=>c===alias||(c.length>4&&(c.includes(alias)||alias.includes(c)))); if(i>=0){mapa[campo]=i;break;} } } }
  return mapa; }
function detectar(cols){ const nc=cols.map(norm); let melhor=null,pt=-1;
  /* regras duras primeiro: um par de colunas que só existe numa base vale mais
     que qualquer pontuação por semelhança */
  const tem=a=>nc.some(c=>c===a||c.includes(a));
  if(tem('nome do responsavel')&&tem('numero da revisao')&&tem('estagio do negocio'))return 'propCab';
  if(tem('codigo da proposta')&&(tem('nome do produto')||tem('valor unitario')))return 'propostas';
  if(tem('saldo a faturar')&&tem('valor faturado'))return 'carteira';
  if(tem('valor total da nf')&&(tem('data emissao')||tem('serie')))return 'notas';
  if(tem('ptc')&&tem('data do pedido'))return 'pedidos';
  if(tem('numero venda de produto omie')||tem('status pedido omie'))return 'vendasOmie';
  if(tem('ordem de servico')&&tem('total do servico'))return 'os';
  if(tem('vigencia inicial completa')&&tem('total do servico'))return 'contratos';
  if(tem('check in verificado')||tem('data de checkout'))return 'interacoes';
  for(const base in ASSINATURAS){ let s=ASSINATURAS[base].filter(a=>nc.some(c=>c===a||c.includes(a))).length*3;
    s+=Object.keys(mapear(cols,base)).length;
    if(s>pt){pt=s;melhor=base;} }
  return pt>=6?melhor:null; }
function objetos(cols,linhas,base){ const m=mapear(cols,base);
  return linhas.map(l=>{const o={_raw:l};for(const c in m)o[c]=l[m[c]];return o;}); }

/* ---------- estado ---------- */
/* a base embutida pode vir comprimida (gzip + base64, data-z="gz"): 2,4 MB de
   JSON viram ~400 KB. Nesse caso BRUTO nasce vazio e lerSeed() o preenche antes
   do arranque — o objeto é o mesmo, só ganha as chaves. */
const _SEED=document.getElementById('seed-dados');
const BRUTO=(_SEED&&_SEED.dataset.z)?{}:JSON.parse((_SEED&&_SEED.textContent)||'{}');
async function lerSeed(){
  if(!_SEED||!_SEED.dataset.z)return;
  const bin=atob(_SEED.textContent.trim()), u8=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);
  const txt=await new Response(new Blob([u8]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  Object.assign(BRUTO,JSON.parse(txt));
}
