  const css=cssPagina();
  const nome=`Relatorio-${REL_PUB[REL_ULTIMO.pub].nome}-LS-Fire-${new Date().toISOString().slice(0,10)}.html`;
  baixar(`<!DOCTYPE html>\n<html lang="pt-BR" data-t="claro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(REL_ULTIMO.tit)}</title><style>${css}</style></head>
<body class="rel-doc"><div class="rel-folhas">${REL_ULTIMO.html}</div>
<script>(function(){var f=document.querySelector('.rel-folhas');function z(){f.style.zoom=Math.min(1,(innerWidth-24)/${REL_PAG.W});}
z();addEventListener('resize',z);addEventListener('beforeprint',function(){f.style.zoom=1});addEventListener('afterprint',z);})();<\/script>
</body></html>`,nome,'text/html;charset=utf-8');
