/* ============================================================
   COCKPIT — entrada e saída de dados, configuração e rótulos
   ============================================================ */
const HTML_ORIG=document.documentElement.outerHTML;
const NOMES_BASE={negocios:'Negócios (CRM)',propostas:'Propostas — itens',propCab:'Propostas — cabeçalho',interacoes:'Interações',
  empresas:'Empresas',historico:'Histórico OMIE',pedidos:'Controle de Pedidos',
  omie:'Omie — itens de venda',vendasOmie:'Vendas (Ploomes × Omie)',contratos:'Contratos de serviço',os:'OS de serviço (Omie)',carteira:'Carteira de faturamento',notas:'Notas fiscais emitidas (faturamento mensal)'};

function abrirModal(id){ document.getElementById(id).classList.add('aberto');
  if(id==='m-dados')listarBases(); if(id==='m-cfg')montarCfg(); if(id==='m-glos')montarGlossario(); }
function fecharModal(id){ document.getElementById(id).classList.remove('aberto'); }
document.addEventListener('keydown',e=>{ if(e.key==='Escape')
  document.querySelectorAll('.modal.aberto').forEach(m=>m.classList.remove('aberto')); });
document.addEventListener('click',e=>{ if(e.target.classList&&e.target.classList.contains('modal'))
  e.target.classList.remove('aberto'); });

/* ---------- rótulos de dados ---------- */
const pluginRot={id:'rot',afterDatasetsDraw(ch,_a,op){
  if(CFG.rotulos===false)return;
  const ctx=ch.ctx, tipo=ch.config.type, horiz=ch.options.indexAxis==='y';
  const area=ch.chartArea||{}; const nCat=Math.max(1,(ch.data.labels||[]).length);
  /* barras lado a lado por categoria: uma por pilha, não uma por série */
  const vis=new Set(ch.data.datasets.map((d,i)=>ch.getDatasetMeta(i).hidden?null:(d.stack||'_'+i)).filter(Boolean)).size||1;
  let FS=11;
  if(tipo==='bar'&&horiz){FS=Math.max(6,Math.min(11,Math.floor((area.bottom-area.top)/(nCat*vis))-2));}
  else if(tipo!=='doughnut'&&tipo!=='pie'){const passo=(area.right-area.left)/nCat;
    if(passo<44)FS=Math.max(6,passo/5.2);}
  if(FS<6)return;
  ctx.save(); ctx.font=`600 ${FS}px 'Segoe UI',Inter,Roboto,Arial,sans-serif`;
  const cor=cssVar('--txt'), cor2=cssVar('--bg2')||cssVar('--bg');
  const multi=st=>ch.data.datasets.filter((d,i)=>d.stack===st&&!ch.getDatasetMeta(i).hidden).length>1;
  ch.data.datasets.forEach((ds,di)=>{
    const meta=ch.getDatasetMeta(di); if(meta.hidden||ds.semRot)return;
    const fmt=fmtDs(ds);
    /* linha longa: rótulo só no último ponto com dado, senão vira um varal de números */
    let ult=-1; if(ds.rotUltimo)ds.data.forEach((v,i)=>{if(v!=null)ult=i;});
    meta.data.forEach((el,i)=>{
      const v=ds.data[i]; if(v==null||v===0)return;
      if(ds.rotUltimo&&i!==ult)return;
      if(tipo==='doughnut'||tipo==='pie'){
        const tot=ds.data.reduce((s,z)=>s+(z||0),0); if(!tot||Math.abs(v/tot)<0.05)return;
        const p=el.tooltipPosition(); ctx.textAlign='center'; ctx.textBaseline='middle';
        ctx.lineWidth=3; ctx.strokeStyle=cor2; ctx.fillStyle=cor;
        const t=fmtD(v/tot*100,0)+'%';   /* fatia: a participação; o valor fica na legenda e no tooltip */
        ctx.strokeText(t,p.x,p.y); ctx.fillText(t,p.x,p.y); return;
      }
      const t=fmt(v); const p=el.tooltipPosition();
      /* empilhado: o rótulo do segmento vai no MEIO dele e só se couber inteiro;
         o total da pilha vai na ponta (abaixo). Antes o texto ia no topo de cada
         segmento, e o do SEQ encostava no do SPV em cima — viravam um borrão. */
      if(ds.stack){
        if(!multi(ds.stack))return;   /* pilha de uma série só: a ponta já traz o total */
        if(horiz&&nCat>8)return;      /* barra deitada com muita categoria: só o total */
        /* só esta série tem valor nesta coluna: o total na ponta já é o mesmo número */
        if(ch.data.datasets.filter((d,j)=>d.stack===ds.stack&&!ch.getDatasetMeta(j).hidden&&+d.data[i]).length<2)return;
        const w=ctx.measureText(t).width, esp=horiz?Math.abs(el.x-el.base):Math.abs(el.base-el.y);
        const larg=horiz?Math.abs(el.height||0):Math.abs(el.width||0);
        if(esp<(horiz?w+8:FS+6)||larg<(horiz?FS+2:w+4))return;
        const x=horiz?(el.x+el.base)/2:el.x, y=horiz?el.y:(el.y+el.base)/2;
        ctx.textAlign='center'; ctx.textBaseline='middle';
        /* etiqueta escura atrás do número: texto branco com contorno ficava borrado
           sobre o laranja e sobre a barra listrada do mês em curso */
        ctx.lineWidth=2.5; ctx.strokeStyle='rgba(20,24,30,.35)'; ctx.strokeText(t,x,y+.5); ctx.fillStyle='#fff'; ctx.fillText(t,x,y+.5); return;
      }
      let x=p.x,y=p.y;
      if(tipo==='line'){ const w=ctx.measureText(t).width;
        x=Math.min(p.x,area.right-w/2-2); y=p.y-7; ctx.textAlign='center'; ctx.textBaseline='bottom';
        if(y-FS<area.top){y=p.y+7;ctx.textBaseline='top';} }
      else if(horiz){x=p.x+5;ctx.textAlign='left';ctx.textBaseline='middle';
        if(x+ctx.measureText(t).width>area.right){x=p.x-5;ctx.textAlign='right';}}
      else{y=p.y-5;ctx.textAlign='center';ctx.textBaseline='bottom';
        if(y-FS<area.top){y=p.y+5;ctx.textBaseline='top';}}
      ctx.lineWidth=3; ctx.strokeStyle=cor2; ctx.fillStyle=cor;
      ctx.strokeText(t,x,y); ctx.fillText(t,x,y);
      /* segunda linha acima do número (ex.: % sobre outra série), na cor da barra */
      const sup=ds.rotSup&&ds.rotSup[i];
      if(sup&&tipo==='bar'&&!horiz&&ctx.textBaseline==='bottom'){ const y2=y-FS-3;
        ctx.fillStyle=Array.isArray(ds.borderColor)?ds.borderColor[i]:(ds.rotSupCor||cor);
        ctx.strokeText(sup,x,y2); ctx.fillText(sup,x,y2); }
    });
  });
  /* total de cada pilha, na ponta da barra */
  const pilhas={};
  ch.data.datasets.forEach((ds,di)=>{ const meta=ch.getDatasetMeta(di);
    if(meta.hidden||ds.semRot||!ds.stack||tipo!=='bar')return;
    (pilhas[ds.stack]=pilhas[ds.stack]||[]).push([ds,meta]); });
  Object.values(pilhas).forEach(lista=>{
    const fmt=fmtDs(lista[0][0]);
    (ch.data.labels||[]).forEach((_,i)=>{
      let tot=0, ponta=null;
      lista.forEach(([ds,meta])=>{ const v=+ds.data[i]||0; if(!v)return; tot+=v; const el=meta.data[i];
        if(el&&(ponta==null||(horiz?el.x>ponta.x:el.y<ponta.y)))ponta=el; });
      if(!tot||!ponta)return;
      const t=fmt(tot); let x=ponta.x,y=ponta.y;
      if(horiz){x+=5;ctx.textAlign='left';ctx.textBaseline='middle';
        if(x+ctx.measureText(t).width>area.right){x=ponta.x-5;ctx.textAlign='right';}}
      else{y-=5;ctx.textAlign='center';ctx.textBaseline='bottom';
        if(y-FS<area.top){y=ponta.y+5;ctx.textBaseline='top';}}
      ctx.lineWidth=3; ctx.strokeStyle=cor2; ctx.fillStyle=cor;
      ctx.strokeText(t,x,y); ctx.fillText(t,x,y);
    });
  });
  ctx.restore();
}};
Chart.register(pluginRot);
function setRotulos(){ CFG.rotulos=CFG.rotulos===false;
  try{localStorage.setItem('lsfire-rot',CFG.rotulos?'1':'0');}catch(e){}
  marcarRot(); render(); }
function marcarRot(){ const b=document.getElementById('bt-rot');
  if(b)b.classList.toggle('on',CFG.rotulos!==false); }

/* ---------- carregar planilhas ---------- */
/* data mais recente DENTRO de cada base — é ela que diz até quando os dados vão,
   não a hora da importação (um export antigo importado hoje continua antigo) */
const DATA_BASE={notas:'dt',carteira:'dt',pedidos:'dt',negocios:'dtAtu',vendasOmie:'dt',propostas:'dt',propCab:'dt',omie:'dt',interacoes:'dt',historico:'dtVenda',os:'dtI'};
function ultimaData(base){ const f=DATA_BASE[base], a=(typeof M!=='undefined'&&M[base])||[]; if(!f)return null;
  let mx=0; a.forEach(x=>{ const d=x&&x[f]; if(d instanceof Date&&!isNaN(d)&&+d<=+HOJE+864e5&&+d>mx)mx=+d; }); return mx?new Date(mx):null; }
const fmtDH=d=>`${fmtData(d)} às ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
function listarBases(){ const imp=(BRUTO._meta&&BRUTO._meta.imp)||{};
  document.getElementById('base-lista').innerHTML=
  Object.keys(NOMES_BASE).map(k=>{ const b=BRUTO[k], u=ultimaData(k), im=imp[k]&&new Date(imp[k].em);
    return `<div class="base-item"><b>${NOMES_BASE[k]}</b>
      <div class="n">${b&&b.rows?fmtN(b.rows.length):0}</div>
      <span style="color:var(--txt3)">${b&&b.cols?b.cols.length:0} colunas${u?` · mais recente ${fmtData(u)}`:''}${im&&!isNaN(im)?` · importada em ${fmtDH(im)}`:''}</span></div>`;}).join(''); }
/* cabeçalho = primeira das 8 linhas iniciais cujos títulos são reconhecidos como
   base; sem isso, a primeira linha com ≥4 células (o Faturamento Mensal tem uma
   linha de título "Mês/Ano · Data" antes do cabeçalho real) */
function linhaCabecalho(mat){
  for(let i=0;i<Math.min(8,mat.length);i++){ const r=(mat[i]||[]).map(c=>c==null?'':String(c).trim());
    if(r.filter(Boolean).length>=3&&detectar(r))return i; }
  for(let i=0;i<Math.min(6,mat.length);i++){
    const c=(mat[i]||[]).filter(x=>x!=null&&String(x).trim()!=='');
    if(c.length>=4)return i; } return 0; }
(function(){ const dz=document.getElementById('dropzona'); if(!dz)return;
  ['dragenter','dragover'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.add('sobre');}));
  ['dragleave','drop'].forEach(e=>dz.addEventListener(e,ev=>{ev.preventDefault();dz.classList.remove('sobre');}));
  dz.addEventListener('drop',ev=>receber(ev.dataTransfer.files)); })();
/* CSV com aspas, quebra de linha no campo e separador ; ou , */
function parseCSV(txt){
  const cab=(txt.split(/\r?\n/)[0]||'');
  const sep=(cab.split(';').length>cab.split(',').length)?';':',';
  const out=[]; let lin=[],campo='',aspas=false;
  for(let i=0;i<txt.length;i++){ const c=txt[i];
    if(aspas){ if(c==='"'){ if(txt[i+1]==='"'){campo+='"';i++;} else aspas=false; } else campo+=c; }
    else if(c==='"')aspas=true;
    else if(c===sep){ lin.push(campo); campo=''; }
    else if(c==='\n'){ lin.push(campo); out.push(lin); lin=[]; campo=''; }
    else if(c==='\r'){}
    else campo+=c; }
  if(campo!==''||lin.length){ lin.push(campo); out.push(lin); }
  return out.map(l=>l.map(v=>{ const t=String(v).trim(); return t===''?null:t; }));
}
/* ---------- Comparativo de Pedidos e Faturamento (planilha oficial) ----------
   Abas "Comparativo Pedidos" e "Comparativo Faturamento": bloco "VALORES (MES
   CORRENTE)" com uma coluna por ano e 12 meses; o de pedidos traz também a
   quantidade. Vira a referência oficial de pedidos (CFG.refOficial) e o
   faturamento realizado oficial (CFG.fatOficial). */
function lerComparativo(wb){
  const aba=re=>wb.SheetNames.find(n=>re.test(norm(n)));
  const ap=aba(/comparativo pedidos/), af=aba(/comparativo faturamento/); if(!ap&&!af)return null;
  const bloco=(nm,re)=>{ if(!nm)return {}; const m=XLSX.utils.sheet_to_json(wb.Sheets[nm],{header:1,raw:true,defval:null,blankrows:false});
    const i=m.findIndex(r=>r&&re.test(norm(r[0]))); if(i<0)return {};
    const anos=m[i].slice(1).map(x=>+x).filter(x=>x>1990&&x<2100), out={};
    anos.forEach((a,j)=>{ out[a]=m.slice(i+1,i+13).map(r=>{ const v=r?r[j+1]:null; return v==null||v===''?null:num(v); }); });
    return out; };
  const dataDe=nm=>{ if(!nm)return null; const r=(XLSX.utils.sheet_to_json(wb.Sheets[nm],{header:1,raw:true,defval:null})[0]||[]); const d=r.find(x=>x instanceof Date); return d?data(d):null; };
  const pv=bloco(ap,/^valores/), pq=bloco(ap,/^por quantidade/), fv=bloco(af,/^valores/);
  const pedidos={}; Object.keys(pv).forEach(a=>{ pedidos[a]={valores:pv[a],qtd:pq[a]||[]}; });
  return {data:dataDe(ap)||dataDe(af),pedidos,fat:fv}; }
function aplicaComparativo(c,arq){
  const ult=a=>{ let k=-1; a.forEach((v,i)=>{ if(v!=null)k=i; }); return k+1; };
  CFG.refOficial=Object.assign({},CFG.refOficial||{});
  Object.entries(c.pedidos).forEach(([a,x])=>{ const n=ult(x.valores); if(!n)return;
    CFG.refOficial[a]={rotulo:`Comparativo de pedidos — planilha oficial${c.data?' de '+fmtData(c.data):''}`,meses:n,
      valores:x.valores.map(v=>v==null?0:v),pedidos:(x.qtd||[]).map(v=>v==null?0:v),data:c.data?c.data.toISOString().slice(0,10):null}; });
  CFG.fatOficial=Object.assign({},CFG.fatOficial||{});
  Object.entries(c.fat).forEach(([a,v])=>{ const n=ult(v); if(n)CFG.fatOficial[a]={meses:n,valores:v,data:c.data?c.data.toISOString().slice(0,10):null}; });
  BRUTO._meta=Object.assign({},BRUTO._meta); BRUTO._meta.imp=Object.assign({},BRUTO._meta.imp,{comparativo:{em:new Date().toISOString(),arq,linhas:Object.keys(c.pedidos).length+Object.keys(c.fat).length}});
  limparCaches(); construir(); marcarUF(); listarBases&&listarBases(); recarregarFiltros(); aplicar(); }
function receber(files){
  /* dado novo é lido na data de hoje, não na referência do arquivo salvo */
  if(REF_DO_ARQUIVO)setRef('');
  const cx=document.getElementById('arqs');
  [...files].forEach(f=>{
    const div=document.createElement('div'); div.className='arq';
    div.innerHTML=`<span>▤</span><span>${esc(f.name)}</span><span class="st" style="color:var(--txt3)">lendo…</span>`;
    cx.appendChild(div);
    const fr=new FileReader();
    const aplica=(cols,rows)=>{
      const base=detectar(cols);
      if(!base)throw new Error('não reconheci a base pelos títulos das colunas');
      const antes=(BRUTO[base]&&BRUTO[base].rows)?BRUTO[base].rows.length:0;
      /* notas fiscais vêm um mês por arquivo: junta com as anteriores, sem repetir
         a mesma nota (nº + série) — a mais recente prevalece */
      if(base==='notas'&&BRUTO.notas&&BRUTO.notas.cols&&BRUTO.notas.cols.join('|')===cols.join('|')){
        const ki=mapear(cols,'notas'), k=r=>String(r[ki.nf])+'|'+String(r[ki.serie]);
        const novos=new Set(rows.map(k)); rows=BRUTO.notas.rows.filter(r=>!novos.has(k(r))).concat(rows); }
      BRUTO[base]={cols,rows};
      /* guarda quando e de qual arquivo veio — vai junto no Salvar */
      BRUTO._meta=Object.assign({},BRUTO._meta); BRUTO._meta.imp=Object.assign({},BRUTO._meta.imp,{[base]:{em:new Date().toISOString(),arq:f.name,linhas:rows.length}});
      const al=antes>rows.length*1.05
        ? ` <span style="color:var(--ale)">(a anterior tinha ${fmtN(antes)} linhas — export menor)</span>`:'';
      construir(); marcarUF(); listarBases(); recarregarFiltros(); aplicar();
      const u=ultimaData(base), velho=u&&(HOJE-u)/864e5>3;
      div.querySelector('.st').innerHTML=`<span style="color:var(--ok)">✓ ${NOMES_BASE[base]} · ${fmtN(rows.length)} linhas</span>`
        +(u?` <span style="color:var(--${velho?'ale':'txt3'})">· registro mais recente ${fmtData(u)}${velho?' — o arquivo não tem nada depois disso':''}</span>`:'')+al
        +(VALIDACAO.datas.length?` <span style="color:var(--err)">· ${fmtN(VALIDACAO.datas.length)} data(s) impossível(is) ignorada(s) (ex.: ${esc(VALIDACAO.datas[0])}) — ver Dados e configurações</span>`:'')
        +(VALIDACAO.numeros.length?` <span style="color:var(--ale)">· ${fmtN(VALIDACAO.numeros.length)} número(s) ambíguo(s) lido(s) como milhar</span>`:''); };
    /* CSV não passa pelo SheetJS: ele lê "11/09/2026" como 9 de novembro */
    if(/\.(csv|tsv|txt)$/i.test(f.name)){
      fr.onload=e=>{ try{
        let txt=String(e.target.result); if(txt.charCodeAt(0)===0xFEFF)txt=txt.slice(1);
        const mat=parseCSV(txt); if(!mat.length)throw new Error('arquivo vazio');
        const hr=linhaCabecalho(mat);
        const cols=(mat[hr]||[]).map(c=>c==null?'':String(c).trim());
        const rows=mat.slice(hr+1).filter(r=>r.some(c=>c!=null&&String(c).trim()!==''))
          .map(r=>cols.map((_,i)=>{ const v=r[i]; return (v==null||v==='')?null:v; }));
        aplica(cols,rows);
      }catch(err){ div.querySelector('.st').innerHTML=`<span style="color:var(--err)">✕ ${esc(err.message)}</span>`; console.error(err); } };
      fr.readAsText(f,'utf-8'); return;
    }
    fr.onload=e=>{ try{
      const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array',cellDates:true});
      /* Comparativo de Pedidos e Faturamento: não é tabela, são blocos por ano */
      const comp=lerComparativo(wb);
      if(comp){ aplicaComparativo(comp,f.name); div.querySelector('.st').innerHTML=`<span style="color:var(--ok)">✓ Comparativo oficial · pedidos ${Object.keys(comp.pedidos).join(', ')} · faturamento ${Object.keys(comp.fat).join(', ')} · data ${fmtData(comp.data)}</span>`; return; }
      /* a aba certa nem sempre é a primeira (a Carteira de 30/10 tem uma "Sheet2" vazia antes) */
      let achou=null;
      for(const nm of wb.SheetNames){ const mat=XLSX.utils.sheet_to_json(wb.Sheets[nm],{header:1,raw:true,defval:null,blankrows:false});
        if(!mat.length)continue; const hr=linhaCabecalho(mat), cols=(mat[hr]||[]).map(c=>c==null?'':String(c).trim());
        if(detectar(cols)){ achou={mat,hr,cols}; break; } }
      if(!achou)throw new Error('não reconheci a base pelos títulos das colunas em nenhuma aba');
      const {mat,hr,cols}=achou;
      const rows=mat.slice(hr+1).filter(r=>r.some(c=>c!=null&&c!==''))
        .map(r=>cols.map((_,i)=>{ let v=r[i];
          if(v instanceof Date)return isNaN(v)?null:new Date(v.getTime()-v.getTimezoneOffset()*6e4).toISOString().slice(0,10);
          if(v==null||v==='')return null; return v; }));
      aplica(cols,rows);
    }catch(err){ div.querySelector('.st').innerHTML=`<span style="color:var(--err)">✕ ${esc(err.message)}</span>`;
      console.error(err); } };
    fr.readAsArrayBuffer(f); }); }

/* ---------- configuração ---------- */
/* As metas são por ano. O modal edita um rascunho de todos os anos: trocar de ano
   no seletor guarda o que foi digitado e abre o outro; Aplicar grava tudo. */
let CFG_RASC=null, CFG_ANO=null;
const _clone=o=>JSON.parse(JSON.stringify(o||{}));
function anosMeta(){ const s=new Set(Object.keys(CFG_RASC||{}));
  (typeof anosBase==='function'?anosBase():[]).forEach(a=>s.add(String(a)));
  s.add(String(HOJE.getFullYear())); s.add(String(HOJE.getFullYear()+1));
  return [...s].filter(a=>+a>=2025).sort(); }
function lerCfgAno(){ const cx=document.getElementById('cfg-corpo'); if(!CFG_RASC||!CFG_ANO||!CFG_RASC[CFG_ANO])return;
  const A=CFG_RASC[CFG_ANO], metas=[], orc=[];
  cx.querySelectorAll('tr[data-lin="v"]').forEach(tr=>{ const g=c=>tr.querySelector(`[data-c="${c}"]`);
    metas.push({vend:g('vend').value.trim(),regiao:g('regiao').value.trim(),seq:num(g('seq').value)||0,spv:num(g('spv').value)||0}); });
  cx.querySelectorAll('tr[data-lin="o"]').forEach(tr=>{ const g=c=>tr.querySelector(`[data-c="${c}"]`);
    orc.push({orc:g('orc').value.trim(),propMes:num(g('propMes').value)||0}); });
  A.metas=metas.filter(m=>m.vend); A.orc=orc.filter(m=>m.orc);
  const is=document.getElementById('cfg-inst-seq'), ip=document.getElementById('cfg-inst-spv');
  if(is)A.seq=num(is.value)||0; if(ip)A.spv=num(ip.value)||0; }
function cfgTrocaAno(a){ lerCfgAno(); montarCfg(a,true); }
function cfgCopiar(de){ CFG_RASC[CFG_ANO]=_clone(CFG_RASC[de]); montarCfg(CFG_ANO,true); }
function cfgNovo(){ CFG_RASC[CFG_ANO]={seq:0,spv:0,metas:[],orc:[]}; montarCfg(CFG_ANO,true); }
function cfgAddLinha(tipo){ lerCfgAno(); const A=CFG_RASC[CFG_ANO];
  if(tipo==='v')A.metas.push({vend:'',regiao:'',seq:0,spv:0}); else A.orc.push({orc:'',propMes:0}); montarCfg(CFG_ANO,true); }
function cfgTira(tipo,i){ lerCfgAno(); const A=CFG_RASC[CFG_ANO]; (tipo==='v'?A.metas:A.orc).splice(i,1); montarCfg(CFG_ANO,true); }
function montarCfg(ano,manter){
  if(!manter||!CFG_RASC)CFG_RASC=_clone(CFG.metasPorAno);
  CFG_ANO=String(ano||EST.ano||HOJE.getFullYear());
  const A=CFG_RASC[CFG_ANO], ref=CFG.refOficial||{};
  const anteriores=Object.keys(CFG_RASC).filter(a=>a!==CFG_ANO&&CFG_RASC[a]).sort();
  const copiarDe=anteriores.filter(a=>+a<+CFG_ANO).pop()||anteriores.pop();
  const sel=`<div class="cfg-ano"><label for="cfg-meta-ano">Metas do ano</label>
      <select id="cfg-meta-ano" class="campo" onchange="cfgTrocaAno(this.value)">${anosMeta().map(a=>`<option ${a===CFG_ANO?'selected':''}>${a}</option>`).join('')}</select>
      <span>${Object.keys(CFG_RASC).filter(a=>CFG_RASC[a]).sort().map(a=>`<b>${a}</b> ${fmtCompacto((num(CFG_RASC[a].seq)||0)+(num(CFG_RASC[a].spv)||0))}`).join(' · ')}</span></div>`;
  let corpo;
  if(!A){
    corpo=`<div class="nota" style="border-left-color:var(--ale)"><b>Ainda não há metas para ${CFG_ANO}.</b> Sem elas, meta e projeção não aparecem nesse ano.</div>
      <div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:10px">
        ${copiarDe?`<button class="btn" onclick="cfgCopiar('${copiarDe}')">Copiar as metas de ${copiarDe}</button>`:''}
        <button class="btn sec" onclick="cfgNovo()">Começar em branco</button></div>`;
  } else {
    const m=A.metas||[], mo=A.orc||[], sS=somar(m,x=>num(x.seq)||0), sP=somar(m,x=>num(x.spv)||0);
    const lin=(tipo,cels,i)=>`<tr data-lin="${tipo}">${cels.map(c=>`<td>${c}</td>`).join('')}<td><button class="cfg-x" title="Remover" onclick="cfgTira('${tipo}',${i})">✕</button></td></tr>`;
    corpo=`<div class="sec"><h3>Meta institucional de ${CFG_ANO}</h3><p>É a meta do time inteiro: vale no Resumo, no termômetro e na projeção quando nenhum vendedor está escolhido.</p></div>
     <div class="g g3">
       <div class="mcampo"><label for="cfg-inst-seq">Meta SEQ (R$)</label><input type="number" id="cfg-inst-seq" value="${num(A.seq)||0}"></div>
       <div class="mcampo"><label for="cfg-inst-spv">Meta SPV (R$)</label><input type="number" id="cfg-inst-spv" value="${num(A.spv)||0}"></div>
       <div class="mcampo"><label>Total</label><input disabled value="${fmtBRL((num(A.seq)||0)+(num(A.spv)||0))}"></div>
     </div>
     <div class="sec"><h3>Metas por vendedor em ${CFG_ANO}</h3></div>
     <div class="tw linhas-cfg"><table><thead><tr><th>Vendedor</th><th>Região / foco</th><th class="n">Meta SEQ</th><th class="n">Meta SPV</th><th></th></tr></thead><tbody>${
       m.map((x,i)=>lin('v',[`<input value="${esc(x.vend||'')}" data-c="vend" aria-label="Vendedor">`,`<input value="${esc(x.regiao||'')}" data-c="regiao" aria-label="Região">`,
         `<input type="number" value="${num(x.seq)||0}" data-c="seq" style="text-align:right" aria-label="Meta SEQ">`,`<input type="number" value="${num(x.spv)||0}" data-c="spv" style="text-align:right" aria-label="Meta SPV">`],i)).join('')}</tbody></table></div>
     <button class="btn sec cfg-mais" onclick="cfgAddLinha('v')">+ vendedor</button>
     <div class="nota">Soma por vendedor: <b>${fmtBRL(sS+sP)}</b> (SEQ ${fmtBRL(sS)} · SPV ${fmtBRL(sP)})${
       (sS!==num(A.seq)||sP!==num(A.spv))&&m.length?' — <b style="color:var(--ale)">diferente da meta institucional</b>':''}</div>
     <div class="sec"><h3>Meta dos analistas de aplicação em ${CFG_ANO}</h3><p>Propostas por mês que cada analista deve produzir.</p></div>
     <div class="tw linhas-cfg"><table><thead><tr><th>Analista</th><th class="n">Propostas/mês</th><th></th></tr></thead><tbody>${
       mo.map((x,i)=>lin('o',[`<input value="${esc(x.orc||'')}" data-c="orc" aria-label="Analista">`,`<input type="number" value="${num(x.propMes)||0}" data-c="propMes" style="text-align:right" aria-label="Propostas por mês">`],i)).join('')}</tbody></table></div>
     <button class="btn sec cfg-mais" onclick="cfgAddLinha('o')">+ analista</button>`;
  }
  document.getElementById('cfg-corpo').innerHTML=`
   <p>O que você mudar aqui vale para todo o painel. Use <b>Salvar</b> no topo para gravar dentro do arquivo.</p>
   ${sel}${corpo}
   <div class="sec"><h3>Parâmetros</h3></div>
   <div class="g g3">
     <div class="mcampo"><label for="cfg-sla">SLA de cotação (dias)</label><input type="number" id="cfg-sla" value="${num(CFG.slaCot)||7}"></div>
     <div class="mcampo"><label for="cfg-parado">Negócio parado a partir de (dias)</label><input type="number" id="cfg-parado" value="${num(CFG.parParado)||30}"></div>
   </div>
   <div class="sec"><h3>Referência oficial de pedidos</h3>
     <p>Planilha oficial de valores do mês (2026: "VALORES (MÊS CORRENTE)" do Controle de Pedidos). É ela que dá o total de cada mês fechado; a soma pedido a pedido só confere (aviso no Resumo e em Vendas quando divergir).</p></div>
   ${tab([{t:'Ano',f:1},{t:'Meses',n:1},{t:'Total',n:1}],
     Object.keys(ref).sort().map(a=>[a,fmtN(ref[a].meses),
       fmtBRL((ref[a].valores||[]).slice(0,ref[a].meses).reduce((s,v)=>s+(v||0),0))]))}
   <div class="nota">Ano sem linha aqui (ex.: um ano novo) usa o detalhe dos pedidos, sem ancoragem. Para trocar ou incluir a referência, carregue o COMPARATIVO atualizado e me avise — a tabela não é editável aqui de propósito, para não virar fonte paralela.</div>
   <div style="display:flex;gap:9px;margin-top:18px;flex-wrap:wrap">
     <button class="btn" onclick="salvarCfg()">Aplicar</button>
     <button class="btn sec" onclick="fecharModal('m-cfg')">Cancelar</button>
   </div>`;
}
function salvarCfg(justMeta){
  lerCfgAno();
  /* metas não mudam em silêncio: toda alteração fica no histórico; ano já
     encerrado exige justificativa */
  { const R=hoje(), mud=Object.keys(Object.assign({},CFG.metasPorAno,CFG_RASC)).filter(a=>JSON.stringify((CFG.metasPorAno||{})[a]||null)!==JSON.stringify(CFG_RASC[a]||null));
    let just='';
    if(mud.some(a=>+a<R.getFullYear()&&CFG.metasPorAno[a])){ just=String(justMeta||'').trim();
      if(!just){ formModal('Alteração de meta de ano encerrado',[{k:'just',rot:`Metas de ${mud.filter(a=>+a<R.getFullYear()).join(', ')} — justificativa (obrigatória)`,tipo:'area',rows:3}],fd=>{
          if(!String(fd.just||'').trim()){ aviso('Informe a justificativa.'); return false; } salvarCfg(String(fd.just).trim()); },'Salvar metas'); return; } }
    mud.forEach(a=>{ const t=x=>x?`SEQ ${fmtBRL(num(x.seq)||0)} · SPV ${fmtBRL(num(x.spv)||0)} · ${(x.metas||[]).length} vendedores${Array.isArray(x.mensalPct)&&x.mensalPct.some(v=>v!==''&&v!=null)?' · distribuição mensal':''}`:'(sem meta)';
      CFG.metasHist.push({id:novoId('h'),em:new Date().toISOString(),meta:`Metas anuais ${a}`,de:t((CFG.metasPorAno||{})[a]),para:t(CFG_RASC[a]),just,antes:_clone((CFG.metasPorAno||{})[a]||null)}); });
    if(mud.length)centralGuardar(); }
  CFG.metasPorAno=_clone(CFG_RASC);
  /* campos antigos acompanham o ano principal, para cópias antigas e o núcleo */
  const P=CFG.metasPorAno[String(CFG.metaAno)];
  if(P){ CFG.metas=P.metas; CFG.metasOrc=P.orc; CFG.metaInstSeq=P.seq; CFG.metaInstSpv=P.spv; }
  CFG.slaCot=num(document.getElementById('cfg-sla').value)||7;
  CFG.parParado=num(document.getElementById('cfg-parado').value)||30;
  limparCaches(); construir(); marcarUF();
  fecharModal('m-cfg'); aplicar();
}

/* ---------- glossário ---------- */
const GLOS=[
 ['Pedidos recebidos','Pedido colocado (booking), não faturamento. Total da empresa: planilha oficial do mês nos meses FECHADOS e soma dos pedidos no mês em curso (Resultados e metas → conciliação). A composição por divisão, vendedor, cliente e produto é a soma dos pedidos, com o valor original de cada um.'],
 ['Diferença de conciliação','Planilha oficial − soma dos pedidos identificados, nos meses fechados. Aparece em linha própria; não é distribuída entre vendedores, clientes ou produtos.'],
 ['Propostas emitidas','Documento enviado ao cliente: uma linha por código de proposta (última revisão), só no Ploomes (desde jul/2026). Não é pedido nem oportunidade.'],
 ['Oportunidade em aberto (pipeline)','Negócio aberto no Ploomes: posição de carteira no último export — não é recortado pelo período. Pipeline bruto = soma do valor integral.'],
 ['Valor ponderado','Valor integral × probabilidade da política única (classificação do negócio: aprovado 100%, em negociação 60%, obra em compra 50%, em disputa 25%, estudo/projeto 10%, não classificado 20%). Probabilidades convencionais, não estatística histórica.'],
 ['Previsão de pedidos','Negócios com previsão de fechamento dentro do horizonte escolhido (a partir da data de referência), ponderados; só entram as classes "Alta confiança — aguardando pedido" e "Provável". Sem data ou com data vencida fica fora.'],
 ['Alta confiança — aguardando pedido','Negócio aprovado, aguardando a PO do cliente. Entra pelo valor cheio (100%). Era chamado "Garantido".'],
 ['Saldo a faturar','Com a Carteira de faturamento carregada: valor do pedido − já faturado (oficial). Sem ela: valor INTEGRAL dos pedidos do Controle não faturados — não é saldo financeiro confirmado.'],
 ['Previsão de faturamento','Saldo a faturar pelo mês de ENTREGA do Controle de Pedidos — aproximação: a carteira não traz data de faturamento. Contratos recorrentes ficam fora (sem cronograma).'],
 ['Faturamento realizado','Notas fiscais emitidas no período (movimento). Total do mês: aba "Comparativo Faturamento" da planilha oficial; detalhe nota a nota: relatório mensal de faturamento (hoje só outubro/2026). Nota anulada ou devolvida não soma. O mês corrente é parcial até a data da planilha. Não tem vendedor nem divisão.'],
 ['Divergência carteira × nota fiscal','Nota emitida para um PV antes da data da carteira, mas a carteira ainda mostra o saldo sem o faturamento correspondente. O painel aponta; quem confirma é o financeiro.'],
 ['Projeção por ritmo','Realizado ÷ fração do ano decorrida até a referência (pela distribuição da meta): onde o ano fecha se mantiver o ritmo. Premissa, não previsão das oportunidades.'],
 ['Meta do período','Meta anual × fração do período até a referência. Sem meta mensal cadastrada, a meta anual é dividida igualmente pelos 12 meses (premissa declarada).'],
 ['Período equivalente','As mesmas datas um ano antes: mês parcial × mesmo trecho; acumulado × acumulado; ano fechado × ano fechado.'],
 ['Data de referência','O "hoje" da análise (padrão: data do computador). Registros posteriores ficam fora; a situação dos negócios é a do último export.'],
 ['Cobertura da meta','Previsão ponderada dos negócios com fechamento até dezembro (com data, não vencidos) ÷ saldo da meta — e não o pipeline inteiro dividido pelo que falta.'],
 ['Win rate','Negócios ganhos ÷ decididos (ganhos + perdidos) no período. Perda do Ploomes sem data de desfecho entra pela última atualização (aproximação).'],
 ['Ciclo de venda','Aba Propostas e conversão: dias da criação da oportunidade até a decisão, nos decididos do recorte. Até ganhar: Ploomes + histórico OMIE; até perder: só o histórico OMIE (o Ploomes não exporta a data da perda).'],
 ['Pedidos ÷ cotações','Aba Desempenho comercial: pedidos do mês ÷ cotações do mês, em quantidade e em R$ (vendido ÷ cotado).'],
 ['FUP (follow-up)','Interação registrada dentro de um negócio no Ploomes (e-mail, WhatsApp, telefone, simples, visita), contada para o responsável do negócio.'],
 ['Velocidade da proposta','Dias do negócio criado até a 1ª proposta, só no Ploomes (desde jul/2026).'],
 ['Categoria fiscal do ERP','Fabricação própria, revenda, locação, serviço — do item da ordem de venda no Omie (confirmada) ou da composição da família (inferida); o resto é não classificado.'],
 ['Família de produto','Linha de produto: no Controle de Pedidos (CMB, SKD, CON, PAR, ITM, PAN) e, nas propostas, pelo nome do item (conjunto motobomba, bomba avulsa, bomba jockey, motor, painel, peças, serviços…).'],
 ['SEQ × SPV','SEQ é Soluções e Equipamentos; SPV é Serviços e Pós-Venda. Registro sem divisão aparece como "Sem divisão identificada" no consolidado.'],
 ['Vínculo inferido','Ligação feita sem identificador (por cliente, valor ou data): marcada com critério e confiança. Com vários candidatos, o painel não escolhe — fica para revisão em Dados e configurações → Vínculos.'],
 ['Rótulos','Liga e desliga os números em cima das barras, fatias e pontos.']];
function montarGlossario(){ document.getElementById('glos-corpo').innerHTML=
  GLOS.map(([t,d])=>`<dt>${esc(t)}</dt><dd>${d}</dd>`).join(''); }

/* ---------- exportar ---------- */
/* Dentro do Claude (artefato) a página não pode baixar sozinha: o arquivo passa
   pelo "downloads" da plataforma, que pede confirmação a quem está vendo. Aberto
   como arquivo local, segue o link de download de sempre. */
let _DL=null;
try{ if(window.claude&&typeof window.claude.use==='function')
  window.claude.use('downloads').then(d=>{_DL=d;}).catch(()=>{}); }catch(e){}
function baixar(txt,nome,tipo){
  const b=new Blob(['\ufeff'+txt],{type:tipo||'text/plain;charset=utf-8'});
  if(_DL){ _DL.save({filename:nome,data:b}).then(()=>aviso('Arquivo salvo: '+nome))
      .catch(e=>{ if(e&&e.code!=='declined')aviso('Não foi possível salvar o arquivo aqui ('+((e&&e.code)||'erro')+').'); });
    return; }
  const u=URL.createObjectURL(b), a=document.createElement('a');
  a.href=u; a.download=nome; document.body.appendChild(a); a.click();
  setTimeout(()=>{URL.revokeObjectURL(u);a.remove();},400); }
/* arquivo binário (PDF): mesmo caminho do baixar(), sem o BOM de texto */
function baixarBlob(b,nome){
  if(_DL){ _DL.save({filename:nome,data:b}).then(()=>aviso('Arquivo salvo: '+nome))
      .catch(e=>{ if(e&&e.code!=='declined')aviso('Não foi possível salvar o arquivo aqui ('+((e&&e.code)||'erro')+').'); });
    return; }
  const u=URL.createObjectURL(b), a=document.createElement('a');
  a.href=u; a.download=nome; document.body.appendChild(a); a.click();
  setTimeout(()=>{URL.revokeObjectURL(u);a.remove();},1500); }
/* aviso na própria página — alert() não aparece dentro do Claude */
function aviso(msg){ let t=document.getElementById('aviso');
  if(!t){ t=document.createElement('div'); t.id='aviso'; t.setAttribute('role','status'); document.body.appendChild(t); }
  t.textContent=msg; t.classList.add('on'); clearTimeout(aviso._t); aviso._t=setTimeout(()=>t.classList.remove('on'),4200); }
function baixarCSV(){
  const tbs=[...document.querySelectorAll('#tela table')];
  if(!tbs.length){aviso('Esta tela não tem tabela para exportar.');return;}
  const lin=[];
  tbs.forEach((t,i)=>{
    const cd=t.closest('.card'); const tit=cd&&cd.querySelector('h4')?cd.querySelector('h4').textContent:'Tabela '+(i+1);
    if(i)lin.push('');
    lin.push('"'+tit.replace(/"/g,'""')+'"');
    [...t.querySelectorAll('tr')].forEach(tr=>{
      lin.push([...tr.children].map(td=>'"'+td.textContent.trim().replace(/\s+/g,' ').replace(/"/g,'""')+'"').join(';'));
    });
  });
  const t=TELAS.find(x=>x.id===EST.tela)||{id:'tela'};
  baixar(lin.join('\n'),`executivo-${t.id}-${new Date().toISOString().slice(0,10)}.csv`,'text/csv;charset=utf-8');
}
/* troca o conteúdo E a tag de abertura (a do seed carrega data-z quando comprimido) */
function trocaBloco(html,id,conteudo,tag){
  const m=html.match(new RegExp('<script id="'+id+'"[^>]*>')); if(!m)return html;
  const i=m.index, abre=tag||m[0];
  const j=html.indexOf('<\/script>',i+m[0].length); if(j<0)return html;
  return html.slice(0,i)+abre+conteudo+html.slice(j); }
async function gzipB64(txt){
  const buf=new Uint8Array(await new Response(new Blob([txt]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
  let s=''; for(let i=0;i<buf.length;i+=0x8000)s+=String.fromCharCode.apply(null,buf.subarray(i,i+0x8000));
  return btoa(s); }
/* Cópia para a diretoria: só o que as telas leem. Sai a base de Interações
   (o executivo não a usa), saem as colunas que nenhum cálculo lê e os campos
   pessoais/sensíveis — CNPJ, contato, inscrição estadual, observações livres.
   Nomes de cliente e valores ficam: sem eles não há drill nem top 10. */
const FORA_DIRETORIA={historico:['cnpj','contato','motivoObs'],propCab:['contato'],empresas:['ie'],
  pedidos:['obs'],omie:['obsItem'],interacoes:'*'};
function baseDiretoria(){
  const out={};
  for(const b in BRUTO){ const B=BRUTO[b];
    if(b==='_meta'){out[b]=B;continue;}   /* origem e data da geração: fica */
    if(!B||!B.cols||FORA_DIRETORIA[b]==='*')continue;
    const m=mapear(B.cols,b), fora=new Set((FORA_DIRETORIA[b]||[]).map(f=>m[f]));
    const keep=[...new Set(Object.values(m))].filter(i=>i!=null&&i>=0&&!fora.has(i)).sort((x,y)=>x-y);
    out[b]={cols:keep.map(i=>B.cols[i]),rows:B.rows.map(r=>keep.map(i=>r[i]))}; }
  return out; }
/* O arquivo gravado é o painel a partir da marca LSF-INICIO, com cabeçalho
   próprio: aberto dentro do Claude, o que vem antes da marca é código da
   plataforma e não pode ir junto. HTML_ORIG é lido antes de qualquer tela ser
   desenhada, então não leva estado da sessão. */
const CAB_LOCAL='<!DOCTYPE html>\n<html lang="pt-BR" data-t="claro">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Painel Executivo Comercial — LS Fire</title>\n';
const CAB_ART='<!doctype html>\n<html lang="pt-BR" data-t="claro" class="artefato">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Painel Executivo LS Fire</title>\n'
  +'<script>(function(){var h=document.documentElement;h.setAttribute("data-t","claro");h.setAttribute("lang","pt-BR");h.classList.add("artefato");})();<\/script>\n';
async function corpoComDados(dados){
  const k=HTML_ORIG.indexOf('<!--LSF-INICIO-->');
  let h=(k>=0?HTML_ORIG.slice(k):HTML_ORIG).replace(/<\/body>\s*<\/html>\s*$/,'');
  h=trocaBloco(h,'seed-dados',await gzipB64(JSON.stringify(dados)),'<script id="seed-dados" type="application/json" data-z="gz">');
  CFG.dataRefSalva=(d=>new Date(d.getTime()-d.getTimezoneOffset()*6e4).toISOString().slice(0,10))(hoje());
  h=trocaBloco(h,'seed-config',JSON.stringify(CFG).replace(/</g,'\\u003c'));
  return h+'\n</body></html>\n'; }
async function salvarHTML(diretoria){
  try{
    const h=await corpoComDados(diretoria?baseDiretoria():BRUTO);
    const d=new Date().toISOString().slice(0,10);
    baixar(CAB_LOCAL+h,`Painel-Executivo-LS-Fire-${diretoria?'diretoria-':''}${d}.html`,'text/html;charset=utf-8');
  }catch(e){ console.error(e); aviso('Não consegui gravar o arquivo: '+e.message); }
}
/* Salvar no Claude: publica uma nova versão deste mesmo link, com as bases e
   metas carregadas. Substitui a versão de todo mundo — por isso pede um
   segundo clique para confirmar. */
async function salvarNoClaude(bt){
  if(!bt.dataset.conf){ bt.dataset.conf='1'; const t0=bt.textContent; bt.textContent='Confirmar: gravar no link?';
    setTimeout(()=>{ delete bt.dataset.conf; bt.textContent=t0; },5000); return; }
  delete bt.dataset.conf; bt.textContent='☁ Salvar no Claude';
  let A=null; try{ A=window.claude&&typeof window.claude.use==='function'?await window.claude.use('artifact'):null; }catch(e){}
  if(!A){ aviso('Salvar no Claude não está disponível aqui. Use ↓ Salvar para ter o arquivo.'); return; }
  try{ bt.disabled=true; aviso('Gravando no Claude…');
    await A.publish(CAB_ART+await corpoComDados(BRUTO));
    aviso('Salvo no Claude. A página vai recarregar com os dados novos.');
  }catch(e){ bt.disabled=false; const c=(e&&e.code)||'';
    if(c==='conflict') aviso('Havia uma versão mais nova; a página vai recarregar com ela. Carregue as planilhas de novo se precisar.');
    else if(['not_writer','not_granted','not_declared','consent_required','capability_disabled','capability_removed'].includes(c)){
      aviso('Aqui você só tem leitura. Use ↓ Salvar para ter sua cópia.'); bt.remove(); }
    else if(c==='too_large') aviso('Ficou grande demais para gravar no Claude. Use ↓ Salvar.');
    else if(c==='rate_limited') aviso('Muitas gravações seguidas. Tente de novo em instantes.');
    else { console.error(e); aviso('Não consegui salvar no Claude ('+(c||(e&&e.message)||'erro')+').'); } }
}

/* CSS da página para os arquivos baixados: os <style> e, na versão com
   styles.css separado, as regras da folha externa (servida pelo mesmo endereço) */
function cssPagina(){ const out=[];
  for(const sh of document.styleSheets){ const n=sh.ownerNode;
    if(n&&n.tagName==='STYLE'){ out.push(n.textContent); continue; }
    try{ out.push([...sh.cssRules].map(r=>r.cssText).join('\n')); }
    catch(e){ if(sh.href)out.push(`@import url("${sh.href}");`); } }
  return out.join('\n'); }
/* indicador de carregamento nos botões de exportação: a planilha é montada no
   mesmo fio da página, então o giro precisa ser desenhado ANTES do trabalho */
function comCarregando(nome){ const f=window[nome]; if(typeof f!=='function'||f._cc)return;
  const g=function(...a){ const ev=window.event, bt=ev&&ev.target&&ev.target.closest?ev.target.closest('button,.btn,.mini'):null;
    if(!bt)return f.apply(this,a);
    if(bt.classList.contains('carregando'))return;
    bt.classList.add('carregando'); bt.setAttribute('aria-busy','true'); bt.disabled=true;
    return new Promise(ok=>requestAnimationFrame(()=>setTimeout(ok,30))).then(()=>f.apply(this,a))
      .catch(e=>{ console.error(e); aviso('Não consegui gerar a planilha: '+(e&&e.message||'erro')); })
      .finally(()=>{ bt.classList.remove('carregando'); bt.removeAttribute('aria-busy'); bt.disabled=false; }); };
  g._cc=1; window[nome]=g; }
['relcPlanilha','fechamentoPlanilha','pqExcel','xlsVendPrev','gbCSV','baixarLista','contratosExcel'].forEach(comCarregando);
/* ---------- arranque ---------- */
function arrancar(){ lerSeed().then(iniciar).catch(e=>{ console.error(e);
  document.getElementById('tela').innerHTML=`<div class="nota">Não consegui abrir a base embutida (${esc(e.message)}).
    Use um navegador atualizado (Chrome, Edge, Firefox ou Safari recentes) ou carregue as planilhas em ↑ Planilhas.</div>`;
  try{ iniciar(); }catch(_){} }); }
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',arrancar);
else arrancar();
